export type ImportRiskKind = "script" | "install_hook" | "binary" | "executable" | "symlink" | "submodule" | "path_traversal";

export type GithubImportSource = { repositoryUrl: string, owner: string, repository: string, requestedRef: string | null, subdirectory: string | null, };

export type ImportFileRecord = { path: string, gitMode: string, gitObjectId: string, sizeBytes: number, sha256: string | null, risks: Array<ImportRiskKind>, extractable: boolean, };

export type ImportComponent = { id: string, kind: ImportComponentKind, displayName: string, pathPrefix: string, compatibility: SkillCompatibility, requestedPermissions: Array<string>, warnings: Array<string>, };

export type LicenseStatus = "detected" | "unknown" | "missing";

export type LicenseFinding = { status: LicenseStatus, spdxId: string | null, name: string | null, filePath: string | null, warning: string | null, };

export type GithubImportPreview = { importId: string, source: GithubImportSource, commitSha: string, contentSha256: string, quarantinePath: string, scannedAt: string, files: Array<ImportFileRecord>, components: Array<ImportComponent>, license: LicenseFinding, permissionRequests: Array<PermissionRequest>, warnings: Array<string>, blocked: boolean, };

export type ImportInstallRequest = { importId: string, workspaceRoot: string, componentIds: Array<string>, };

export type InstalledImportVersion = { installationId: string, versionId: string, source: GithubImportSource, commitSha: string, contentSha256: string, installedPath: string, componentIds: Array<string>, installedAt: string, active: boolean, };

export type ImportComparison = { installationId: string, activeCommitSha: string, candidateCommitSha: string, added: Array<string>, changed: Array<string>, removed: Array<string>, };
